let key! dir p =
  Digest.hex (Hash.file! Digest.Sha256 (Path.join dir p))

let run! dir =
  let rels = List.filter_map (Path.relative_to dir) (FS.glob_in ./**/* dir) |> List.map Path.to_string |> List.sort;
  let groups = List.fold_left (fn m r -> Map.update (key! dir (Path.of_string r)) [] (fn l -> r :: l) m) Map.empty rels;
  let gs = Map.values groups |> List.map List.reverse |> List.filter (fn g -> List.length g >= 2) |> List.sort_by (fn g -> List.head! g);
  List.each (fn g -> ()) [];
  let text = String.join "\n\n" (List.map (fn g -> String.join "\n" g) gs);
  if List.empty? gs then () else IO.println text

match Proc.args () with
| [] ->
  IO.println_err "usage: prog DIR"
  Proc.exit 2
| d :: _ ->
  let dir = Path.of_string d;
  if FS.dir? dir then run! dir else (IO.println_err "not a directory: %{d}"; Proc.exit 1)
EOF
