uses {IO, Proc}
import IO
import List
import Map
import Regex
import Int
import String

let line_re = r/^ *([^ ]+) +((?:[0-9]+h)?(?:[0-9]+m)?(?:[0-9]+s)?) *$/
let part_re = r/^(?:([0-9]+)h)?(?:([0-9]+)m)?(?:([0-9]+)s)?$/

let num s = Int.of_string s |> Result.default 0

let fmt secs =
  let h = secs / 3600;
  let m = (secs % 3600) / 60;
  let s = secs % 60;
  let out = (if h > 0 then "%{h}h" else "") ++ (if m > 0 then "%{m}m" else "") ++ (if s > 0 then "%{s}s" else "");
  if out == "" then "0s" else out

let fail n =
  IO.println_err "line %{n}: invalid line"
  Proc.exit 1

let step (n, acc) line =
  if String.empty? (String.trim line) then (n + 1, acc)
  else
    match Regex.capture line_re line with
    | [_, name, dur] ->
      if String.empty? dur then fail n
      else
        match Regex.capture part_re dur with
        | [_, h, m, s] ->
          let total = num h * 3600 + num m * 60 + num s;
          (n + 1, Map.update name 0 (fn x -> x + total) acc)
        | _ -> fail n
    | _ -> fail n

let (_, acc) = IO.stdin_lines () |> Stream.fold_left step (1, Map.empty)
let names = List.sort (Map.keys acc)
List.each (fn k -> IO.println "%{k} %{fmt (Map.get! k acc)}") names
IO.println "total %{fmt (List.sum (Map.values acc) |> Option.default 0)}"
EOF
