uses {IO, Proc}
import IO
import List
import String
import Map
import Regex

let pat = r/^(\S+) +(?:(\d+)h)?(?:(\d+)m)?(?:(\d+)s)?$/

let num s = match Int.of_string s with
  | Ok n -> n
  | Error _ -> 0

let fmt secs =
  let h = secs / 3600;
  let m = (secs % 3600) / 60;
  let s = secs % 60;
  let out = (if h > 0 then "%{h}h" else "") ++ (if m > 0 then "%{m}m" else "") ++ (if s > 0 then "%{s}s" else "");
  if out == "" then "0s" else out

let parse line =
  let t = String.trim line;
  let c = Regex.capture pat t;
  match c with
  | [] -> Error "bad line"
  | _ ->
    let dur = String.slice (String.length (List.get! 1 c)) (String.length t) t |> String.trim;
    if dur == "" then Error "bad line"
    else Ok (List.get! 1 c, num (List.get! 2 c) * 3600 + num (List.get! 3 c) * 60 + num (List.get! 4 c))

let lines = IO.read_all! () |> String.lines |> List.indexed

let results = lines |> List.filter (fn p -> String.trim p.1 != "") |> List.map (fn p -> (p.0 + 1, parse p.1))

let bad = results |> List.find (fn r -> Result.error? r.1)

match bad with
| Some r ->
  IO.println_err "line %{r.0}: invalid line"
  Proc.exit 1
| None ->
  let m = results |> List.fold_left (fn acc r -> match r.1 with
    | Ok (n, s) -> Map.update n 0 (fn x -> x + s) acc
    | Error _ -> acc) Map.empty
  let total = Map.values m |> List.sum |> Option.default 0
  Map.keys m |> List.sort |> List.each (fn k -> IO.println "%{k} %{fmt (Map.get! k m)}")
  IO.println "total %{fmt total}"
EOF
