uses {IO}
import IO
import List
import Map
import String
import Decode
import Int

let rec_dec = Decode.map2 (fn e m -> (e, m)) (Decode.field "endpoint" Decode.string) (Decode.field "ms" Decode.int)

let rank p n = (p * n + 99) / 100

let pick vs r = Option.default 0 (List.get (r - 1) vs)

let main () =
  let lines = String.lines (IO.read_all! ());
  let step = fn (acc: (Map (List Int), Int)) line ->
    if String.trim line == "" then acc
    else
      match Decode.run rec_dec line with
      | Ok (e, m) ->
        if m >= 0 then (Map.update e (fn o -> Some (m :: Option.default [] o)) acc.0, acc.1)
        else (acc.0, acc.1 + 1)
      | Error _ -> (acc.0, acc.1 + 1);
  let res = List.fold_left step (Map.empty, 0) lines;
  List.each (fn e ->
    let vs = List.sort (Option.default [] (Map.get e res.0));
    let n = List.length vs;
    IO.println "%{e} count=%{n} p50=%{pick vs (rank 50 n)} p95=%{pick vs (rank 95 n)}") (List.sort (Map.keys res.0))
  if res.1 > 0 then IO.println "skipped %{res.1}" else ()

main ()
EOF
